#pragma once

#include <array>
#include <cstdint>
#include <stdexcept>
#include <vector>

namespace rl::flicky {

class FlickyCollisionError : public std::runtime_error {
public:
    using std::runtime_error::runtime_error;
};

constexpr int flickyMapWidth = 32;
constexpr int flickyMapHeight = 28;
constexpr int flickyMapSize = flickyMapWidth * flickyMapHeight;
using FlickyCollisionGrid = std::array<std::uint8_t, flickyMapSize>;

// The first two rows are generated by the game and cannot be serialized.
[[nodiscard]] FlickyCollisionGrid decodeFlickyCollision(
    const std::vector<std::uint8_t> &stream);
[[nodiscard]] std::vector<std::uint8_t> encodeFlickyCollision(
    const FlickyCollisionGrid &grid);

} // namespace rl::flicky
